actions.apply:
& fsutil.exe behavior set disabledeletenotify NTFS 0 | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'fsutil failed' }
foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { [string]$_.DriveType -eq 'Fixed' -and $_.DriveLetter -and [string]$_.FileSystem -eq 'NTFS' })) {
  try { Optimize-Volume -DriveLetter $v.DriveLetter -ReTrim -ErrorAction Stop } catch { }
}

$cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
if (-not $cs.AutomaticManagedPagefile) {
  Set-CimInstance -InputObject $cs -Property @{ AutomaticManagedPagefile = $true } -ErrorAction Stop
}
